mapper.select:
SELECT COUNT(1) FROM TBL_ZGZZ_ISSUESILIST
WHERE 1=1

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_ISSUESILIST
WHERE STATUS IN (6, 8, 11)

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_RECTIFICATIONIMPL
WHERE 1=1

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_ISSUESILIST
WHERE STATUS = 9

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_RECTIFICATIONPLAN
WHERE 1=1

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_ISSUESILIST
WHERE STATUS IN (3, 4, 5)

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_ISSUESILIST
WHERE STATUS IN (6, 7, 8, 10, 11)

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_WGZZ_WGZZ
WHERE ISACCEPTED = 1

    AND EXTRACT(YEAR FROM IMPCREATEUSERNAME) = #{year}

SELECT COUNT(1) FROM TBL_WGZZ_WGHS
WHERE STATUS = 5

    AND EXTRACT(YEAR FROM IMPCREATEUSERNAME) = #{year}

SELECT COUNT(1) FROM TBL_WGZZ_WGJY_YS
WHERE YSSTUTS = 2

    AND EXTRACT(YEAR FROM IMPCREATEUSERNAME) = #{year}

SELECT COUNT(1) FROM TBL_WGZZ_WGZZ
WHERE ISACCEPTED = 0 OR ISACCEPTED IS NULL

    AND EXTRACT(YEAR FROM IMPCREATEUSERNAME) = #{year}

SELECT AVG(RESULTSTATUS) FROM TBL_ZGZZ_RCTEVALUATION
WHERE RESULTSTATUS IS NOT NULL AND RESULTSTATUS > 0

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}

SELECT COUNT(1) FROM TBL_ZGZZ_ISSUESILIST
WHERE STATUS IS NOT NULL

    AND EXTRACT(YEAR FROM CREATETIME) = #{year}
